values.content:
Generate insurance quote for:

Name: {{ $json.first_name }} {{ $json.last_name }}
Age: {{ $json.age }}
Income: {{ $json.income }}
Coverage Type: {{ $json.coverage_type }}
Coverage Amount Requested: {{ $json.coverage_amount || 'Not specified' }}
Smoker: {{ $json.smoker || 'No' }}
Health Status: {{ $json.health_status || 'Good' }}
Employment: {{ $json.employment_status || 'Employed' }}
Family Status: {{ $json.marital_status || 'Single' }}, {{ $json.dependents || 0 }} dependents
Existing Coverage: {{ $json.has_existing_coverage || 'None' }}

Agent: {{ $env.AGENT_NAME }}
Agency: {{ $env.AGENCY_NAME }}

parameters.jsCode:
const lead = $input.first().json;
const aiQuote = $input.last().json;

let quote;
try {
  const content = aiQuote.choices[0].message.content;
  quote = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  // Fallback quote
  quote = {
    primary_quote: {
      coverage_type: lead.coverage_type,
      coverage_amount: '$500,000',
      monthly_premium: '$75',
      annual_premium: '$900',
      key_benefits: ['Financial protection for family', 'Fixed premiums', 'Convertible option']
    },
    recommended_upgrades: [],
    total_annual_value: '$900',
    comparison_to_competitors: 'Competitive rates',
    next_steps: 'Schedule a call to finalize',
    personalized_message: 'Great coverage for your situation'
  };
}

const quoteId = `Q-${Date.now()}-${lead.id}`;

return {
  json: {
    quote_id: quoteId,
    lead_id: lead.id,
    lead_name: `${lead.first_name} ${lead.last_name}`,
    lead_email: lead.email,
    lead_phone: lead.phone,
    quote_data: quote,
    generated_at: new Date().toISOString(),
    expires_at: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString() // 30 days
  }
};

