Benefits: {{ JSON.stringify($json.quote_data.primary_quote.key_benefits) }}
Personal Note: {{ $json.quote_data.personalized_message }}

Agent: {{ $env.AGENT_NAME }}
Phone: {{ $env.AGENT_PHONE }}
Booking: {{ $env.CALENDAR_BOOKING_LINK }}

Expires: {{ DateTime.fromISO($json.expires_at).toFormat('MMMM d, yyyy') }}

parameters.jsCode:
const quoteInfo = $input.first().json;
const emailAI = $input.last().json;

let email;
try {
  const content = emailAI.choices[0].message.content;
  email = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  // Fallback
  email = {
    subject: `Your ${quoteInfo.quote_data.primary_quote.coverage_type} Quote - ${quoteInfo.quote_data.primary_quote.monthly_premium}/month`,
    body: `Hi ${quoteInfo.lead_name.split(' ')[0]},\n\nHere's the quote you requested for ${quoteInfo.quote_data.primary_quote.coverage_type}.\n\nCoverage: ${quoteInfo.quote_data.primary_quote.coverage_amount}\nMonthly Premium: ${quoteInfo.quote_data.primary_quote.monthly_premium}\nAnnual Premium: ${quoteInfo.quote_data.primary_quote.annual_premium}\n\n${quoteInfo.quote_data.personalized_message}\n\nThis quote is valid until ${new Date(quoteInfo.expires_at).toLocaleDateString()}.\n\nLet's schedule a call to discuss: ${process.env.CALENDAR_BOOKING_LINK}\n\nBest regards,\n${process.env.AGENT_NAME}\n${process.env.AGENT_PHONE}`
  };
}

return {
  json: {
    ...quoteInfo,
    email_content: email
  }
};
